/**
 * Tests for the orchestrator → export seam.
 *
 * The point of this service is REFUSAL, so the tests that matter are the ones
 * that prove it refuses: a tampered leaf manifest, a forged digest, a revoked
 * signature. A gate only ever seen to pass has not been tested.
 */

import { describe, expect, it, vi, beforeEach } from 'vitest';
import crypto from 'crypto';

// ── Mocks ───────────────────────────────────────────────────────────────────
// The service imports getRun / findActiveReleaseSignature from the orchestrator
// (DB-backed) and computeBoundPayloadDigestFromComponents (pure). We mock the
// two DB functions and let the REAL digest function run — the digest is the
// thing under test, so stubbing it would test nothing.

const mockGetRun = vi.fn();
const mockFindActiveReleaseSignature = vi.fn();

vi.mock('../../submission-package-orchestrator.js', async () => {
  const actual = await vi.importActual<
    typeof import('../../submission-package-orchestrator.js')
  >('../../submission-package-orchestrator.js');
  return {
    ...actual,
    getRun: (...args: unknown[]) => mockGetRun(...args),
    findActiveReleaseSignature: (...args: unknown[]) => mockFindActiveReleaseSignature(...args),
  };
});

vi.mock('../../../db.js', () => ({
  pool: { query: vi.fn(async () => ({ rows: [] })) },
  db: { execute: vi.fn(async () => ({ rows: [] })) },
}));

vi.mock('../../../lib/unified-ai-client.js', () => ({
  ai: { complete: vi.fn(async () => '') },
}));

import {
  resolveSignedPackageForExport,
  verifyLeafBytes,
  refusalHttpStatus,
} from '../signed-package-export';
import { computeBoundPayloadDigestFromComponents } from '../../submission-package-orchestrator';
import { sealSignPayloadDigest } from '../sign-payload-seal';
import type { ECTDLeaf } from '../ectd4-validator';

// ── Fixtures ────────────────────────────────────────────────────────────────

const ORG = 42;
const RUN_ID = 'run-0001';
const SEAL_KEY = 'test-audit-hmac-key-0123456789abcdef';
const SEALED_ENV = { AUDIT_HMAC_KEY: SEAL_KEY } as unknown as NodeJS.ProcessEnv;

function leaf(overrides: Partial<ECTDLeaf> = {}): ECTDLeaf {
  const payload = overrides.filePath ?? 'm3/32s1/ds.pdf';
  return {
    sectionCode: 'm3.2.S.1',
    title: 'Drug Substance General Information',
    checksum: crypto.createHash('md5').update(payload).digest('hex'),
    checksumType: 'md5',
    operation: 'new',
    filePath: payload,
    mimeType: 'application/pdf',
    fileSize: 2048,
    ...overrides,
  };
}

const SIGNED_LEAVES: ECTDLeaf[] = [
  leaf({ filePath: 'm3/32s1/ds.pdf' }),
  leaf({ filePath: 'm3/32s7/stability.pdf', sectionCode: 'm3.2.S.7', title: 'Stability' }),
];

const VALIDATOR_OUTCOME = {
  gatewayReady: true,
  hardenedScore: 96,
  summary: {
    errors: 0,
    warnings: 1,
    infos: 0,
    sectionsPresent: 15,
    sectionsRequired: 15,
    sectionsMissing: [],
  },
};

const SNAPSHOT = {
  leaves: SIGNED_LEAVES,
  backboneXml: '<?xml version="1.0"?><ectd:ectd/>',
  validatorOutcome: VALIDATOR_OUTCOME,
  submissionId: 'sub-001',
  organizationId: ORG,
  applicationNumber: 'IND123456',
  sequenceNumber: '0000',
  region: 'US' as const,
  submissionType: 'IND',
  totalSizeBytes: 4096,
};

/** The digest the signing path would have produced for SNAPSHOT. */
function digestFor(snapshot: typeof SNAPSHOT): string {
  return computeBoundPayloadDigestFromComponents({
    leaves: snapshot.leaves,
    validatorOutcome: snapshot.validatorOutcome,
    submissionId: snapshot.submissionId,
    applicationNumber: snapshot.applicationNumber,
    region: snapshot.region,
    submissionType: snapshot.submissionType,
    organizationId: snapshot.organizationId,
    backboneXml: snapshot.backboneXml || undefined,
  });
}

function runWithSignStep(opts: {
  status?: string;
  payload?: Record<string, unknown> | null;
  rawOutputRef?: string;
  omitSignStep?: boolean;
}) {
  const steps = [
    { key: 'package.assemble', status: 'complete', inputHash: 'a', dependsOn: [] },
    { key: 'package.validate', status: 'complete', inputHash: 'b', dependsOn: ['package.assemble'] },
  ];
  if (!opts.omitSignStep) {
    steps.push({
      key: 'package.sign',
      status: opts.status ?? 'complete',
      inputHash: 'c',
      dependsOn: ['package.validate'],
      ...(opts.rawOutputRef !== undefined
        ? { outputRef: opts.rawOutputRef }
        : opts.payload === null
          ? {}
          : { outputRef: JSON.stringify(opts.payload) }),
    } as never);
  }
  return {
    runId: RUN_ID,
    organizationId: ORG,
    submissionId: 'sub-001',
    applicationNumber: 'IND123456',
    region: 'US',
    submissionType: 'IND',
    startedAt: '2026-09-01T00:00:00Z',
    status: 'complete',
    steps,
  };
}

/** The active release signature, with its §11.50 manifestation. */
const ACTIVE_SIGNATURE = {
  id: 7,
  signerId: 12,
  signerName: 'A. Reviewer',
  signerTitle: 'Head of Regulatory Affairs',
  meaning: 'approval',
  signedAt: '2026-09-20T14:03:05.000Z',
};

/** A fully valid, sealed, signed payload for the happy path. */
function validPayload(snapshot = SNAPSHOT) {
  const payloadDigest = digestFor(snapshot);
  return {
    payloadDigest,
    payloadSeal: sealSignPayloadDigest(payloadDigest, ORG, SEALED_ENV),
    signatureId: 7,
    awaitingSince: '2026-09-01T00:05:00Z',
    signedSnapshot: snapshot,
  };
}

beforeEach(() => {
  vi.clearAllMocks();
  mockFindActiveReleaseSignature.mockResolvedValue(ACTIVE_SIGNATURE);
});

// ── Happy path ──────────────────────────────────────────────────────────────

describe('resolveSignedPackageForExport — accepts an intact signed package', () => {
  it('exports the exact recorded applicant snapshot the signature binds', async () => {
    const recordedPackageIdentity = { version: 1 as const, identity: {
      programId: '11111111-1111-4111-8111-111111111111', applicationNumber: '123456',
      applicantName: 'Recorded Sponsor', applicantSponsorId: '22222222-2222-4222-8222-222222222222',
      applicantId: '123456789', contact: { name: 'Contact', phone: '+1 555 0100', email: 'ra@example.test' },
    } };
    const snapshot = { ...SNAPSHOT, recordedPackageIdentity };
    const payloadDigest = computeBoundPayloadDigestFromComponents({ ...snapshot, backboneXml: snapshot.backboneXml });
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: { payloadDigest,
      payloadSeal: sealSignPayloadDigest(payloadDigest, ORG, SEALED_ENV), signatureId: 7,
      awaitingSince: '2026-09-01T00:05:00Z', signedSnapshot: snapshot } }));
    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG, env: SEALED_ENV });
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.descriptor.recordedPackageIdentity).toEqual(recordedPackageIdentity);
  });

  it('refuses an applicant contact altered inside an otherwise intact frozen record', async () => {
    const recordedPackageIdentity = { version: 1 as const, identity: {
      programId: '11111111-1111-4111-8111-111111111111', applicationNumber: '123456',
      applicantName: 'Recorded Sponsor', applicantSponsorId: '22222222-2222-4222-8222-222222222222',
      applicantId: '123456789', contact: { name: 'Contact', phone: '+1 555 0100', email: 'ra@example.test' },
    } };
    const snapshot = { ...SNAPSHOT, recordedPackageIdentity };
    const payloadDigest = computeBoundPayloadDigestFromComponents({ ...snapshot, backboneXml: snapshot.backboneXml });
    const altered = { ...snapshot, recordedPackageIdentity: { ...recordedPackageIdentity, identity: {
      ...recordedPackageIdentity.identity, contact: { ...recordedPackageIdentity.identity.contact, email: 'changed@example.test' },
    } } };
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: { payloadDigest,
      payloadSeal: sealSignPayloadDigest(payloadDigest, ORG, SEALED_ENV), signatureId: 7,
      awaitingSince: '2026-09-01T00:05:00Z', signedSnapshot: altered } }));
    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG, env: SEALED_ENV });
    expect(result).toMatchObject({ ok: false, refusal: 'digest-drift' });
  });

  it('returns the signed manifest when every control verifies', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: validPayload() }));

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });

    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.descriptor.leaves).toHaveLength(2);
    expect(result.descriptor.signatureId).toBe(7);
    expect(result.descriptor.sealVerdict).toBe('ok');
    expect(result.descriptor.gatewayReady).toBe(true);
    expect(result.descriptor.applicationNumber).toBe('IND123456');
  });

  it('carries the signer, time and meaning of the active signature (§11.50, review P11-4)', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: validPayload() }));

    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG, env: SEALED_ENV });

    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.descriptor).toMatchObject({
      signatureId: 7,
      signerId: 12,
      signerName: 'A. Reviewer',
      signerTitle: 'Head of Regulatory Affairs',
      signatureMeaning: 'approval',
      signedAt: '2026-09-20T14:03:05.000Z',
    });
  });

  it('passes a missing manifestation field through as null, not as a stand-in', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: validPayload() }));
    mockFindActiveReleaseSignature.mockResolvedValue({
      ...ACTIVE_SIGNATURE,
      signerTitle: null,
      meaning: null,
    });

    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG, env: SEALED_ENV });

    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.descriptor.signerTitle).toBeNull();
    expect(result.descriptor.signatureMeaning).toBeNull();
    expect(result.descriptor.signerName).toBe('A. Reviewer');
  });

  it('accepts an unsealed run under an unsealed posture', async () => {
    const digest = digestFor(SNAPSHOT);
    mockGetRun.mockResolvedValue(
      runWithSignStep({
        payload: { payloadDigest: digest, signatureId: 7, signedSnapshot: SNAPSHOT },
      }),
    );

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: {} as NodeJS.ProcessEnv,
    });

    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.descriptor.sealVerdict).toBe('unsealed');
  });
});

// ── The refusals that justify the gate ──────────────────────────────────────

describe('resolveSignedPackageForExport — refuses tampered packages', () => {
  it('REFUSES when a leaf was swapped after signing (digest drift)', async () => {
    // The attack: edit the steps JSONB to point at a different leaf manifest,
    // leaving the stored digest + seal untouched. The recomputed digest moves.
    const tampered = {
      ...SNAPSHOT,
      leaves: [leaf({ filePath: 'm3/32s1/ATTACKER.pdf' }), SIGNED_LEAVES[1]],
    };
    const payload = validPayload(SNAPSHOT); // digest + seal over the ORIGINAL
    mockGetRun.mockResolvedValue(
      runWithSignStep({ payload: { ...payload, signedSnapshot: tampered } }),
    );

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });

    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('digest-drift');
    expect(result.detail).toContain('changed after signing');
  });

  it('REFUSES when the digest was forged to match a tampered manifest (seal failure)', async () => {
    // The smarter attack: swap the manifest AND recompute the stored digest so
    // they agree. The server-keyed HMAC is what they cannot forge.
    const tampered = {
      ...SNAPSHOT,
      leaves: [leaf({ filePath: 'm3/32s1/ATTACKER.pdf' })],
    };
    mockGetRun.mockResolvedValue(
      runWithSignStep({
        payload: {
          payloadDigest: digestFor(tampered), // self-consistent...
          payloadSeal: sealSignPayloadDigest(digestFor(SNAPSHOT), ORG, SEALED_ENV), // ...but sealed over the original
          signatureId: 7,
          signedSnapshot: tampered,
        },
      }),
    );

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });

    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('seal-failed');
  });

  it('REFUSES when a seal exists but the key is gone (unverifiable control)', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: validPayload() }));

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: {} as NodeJS.ProcessEnv, // key absent, but a seal is stored
    });

    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('seal-failed');
  });

  it('REFUSES when the signature was superseded or rolled back', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: validPayload() }));
    mockFindActiveReleaseSignature.mockResolvedValue(null);

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });

    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('signature-revoked');
  });

  it('REFUSES as signature-unverifiable — NOT revoked — when the signature lookup could not run (WO-16B finding 14)', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ payload: validPayload() }));
    const notRun = Object.assign(new Error('release-signature lookup could not be run: 42703: column "bound_payload_digest" does not exist'), {
      name: 'VerificationUnavailableError',
      detail: '42703: column "bound_payload_digest" does not exist',
      what: 'release-signature lookup',
    });
    mockFindActiveReleaseSignature.mockRejectedValue(notRun);

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });

    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('signature-unverifiable');
    expect(result.detail).toMatch(/NOT been found revoked/);
    expect(refusalHttpStatus('signature-unverifiable')).toBe(503);
  });

  it('REFUSES a change to the identity tuple (org swap) even with intact leaves', async () => {
    // Cross-tenant re-pointing: same package bytes, different owning org.
    const reassigned = { ...SNAPSHOT, organizationId: 999 };
    const payload = validPayload(SNAPSHOT);
    mockGetRun.mockResolvedValue(
      runWithSignStep({ payload: { ...payload, signedSnapshot: reassigned } }),
    );

    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });

    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('digest-drift');
  });
});

describe('resolveSignedPackageForExport — refuses unsigned / incomplete states', () => {
  it('refuses an unknown or cross-tenant run', async () => {
    mockGetRun.mockResolvedValue(null);
    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('run-not-found');
  });

  it('refuses a run with no package.sign step', async () => {
    mockGetRun.mockResolvedValue(runWithSignStep({ omitSignStep: true }));
    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('not-signed');
  });

  it('refuses a run still awaiting a signature', async () => {
    mockGetRun.mockResolvedValue(
      runWithSignStep({ status: 'awaiting-signature', payload: validPayload() }),
    );
    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('awaiting-signature');
  });

  it('refuses a skipped signature gate rather than treating it as signed', async () => {
    mockGetRun.mockResolvedValue(
      runWithSignStep({ status: 'skipped', rawOutputRef: 'skipped:not-required' }),
    );
    const result = await resolveSignedPackageForExport({ runId: RUN_ID, organizationId: ORG });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('not-signed');
  });

  it('refuses a legacy run signed before snapshot persistence', async () => {
    const digest = digestFor(SNAPSHOT);
    mockGetRun.mockResolvedValue(
      runWithSignStep({
        payload: {
          payloadDigest: digest,
          payloadSeal: sealSignPayloadDigest(digest, ORG, SEALED_ENV),
          signatureId: 7,
          // no signedSnapshot
        },
      }),
    );
    const result = await resolveSignedPackageForExport({
      runId: RUN_ID,
      organizationId: ORG,
      env: SEALED_ENV,
    });
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.refusal).toBe('snapshot-missing');
  });
});

// ── Byte verification ───────────────────────────────────────────────────────

describe('verifyLeafBytes', () => {
  it('passes when rendered bytes hash to the signed checksums', () => {
    const buffers: Record<string, Buffer> = {};
    for (const l of SIGNED_LEAVES) buffers[l.filePath] = Buffer.from(l.filePath);
    const v = verifyLeafBytes(SIGNED_LEAVES, buffers);
    expect(v.ok).toBe(true);
    expect(v.missing).toHaveLength(0);
    expect(v.mismatched).toHaveLength(0);
  });

  it('fails closed on a missing leaf rather than passing it', () => {
    const buffers = { [SIGNED_LEAVES[0].filePath]: Buffer.from(SIGNED_LEAVES[0].filePath) };
    const v = verifyLeafBytes(SIGNED_LEAVES, buffers);
    expect(v.ok).toBe(false);
    expect(v.missing).toContain(SIGNED_LEAVES[1].filePath);
  });

  it('reports a leaf whose bytes do not match the signed checksum', () => {
    const buffers: Record<string, Buffer> = {};
    for (const l of SIGNED_LEAVES) buffers[l.filePath] = Buffer.from(l.filePath);
    buffers[SIGNED_LEAVES[0].filePath] = Buffer.from('substituted content');
    const v = verifyLeafBytes(SIGNED_LEAVES, buffers);
    expect(v.ok).toBe(false);
    expect(v.mismatched).toHaveLength(1);
    expect(v.mismatched[0].filePath).toBe(SIGNED_LEAVES[0].filePath);
  });
});

// ── Status mapping ──────────────────────────────────────────────────────────

describe('refusalHttpStatus', () => {
  it('maps integrity failures to 422, distinct from workflow-state 409s', () => {
    expect(refusalHttpStatus('seal-failed')).toBe(422);
    expect(refusalHttpStatus('digest-drift')).toBe(422);
    expect(refusalHttpStatus('awaiting-signature')).toBe(409);
    expect(refusalHttpStatus('not-signed')).toBe(409);
    expect(refusalHttpStatus('signature-revoked')).toBe(409);
    expect(refusalHttpStatus('snapshot-missing')).toBe(409);
    expect(refusalHttpStatus('run-not-found')).toBe(404);
  });
});

/**
 * @fileoverview Resolve the release-signature state for a submission at dispatch time
 * @module server/services/ectd/release-signature-status
 *
 * The dispatch path (`assess-dispatch-readiness`) is keyed on the submissions
 * SPINE — `ectd_sequences` → `submission_leaves`. The e-signature lives on the
 * ORCHESTRATOR spine — `submission_orchestrator_runs.steps[package.sign]`. The
 * two join only through `submissions.id`:
 *
 *     ectd_sequences.submission_id ──┐
 *                                    ├──▶ submissions.id
 *     submission_orchestrator_runs.submission_id_fk ──┘
 *
 * This module walks that join and returns a verdict the pure dispatch gate can
 * judge. It reuses `resolveSignedPackageForExport` for the actual integrity
 * verification so there is ONE implementation of "does this signature still
 * bind its package" rather than a second, drifting copy.
 *
 * ## …and why binding its package is not enough
 *
 * `resolveSignedPackageForExport` answers "does this signature still bind the
 * package it was taken over", by recomputing the digest from the frozen
 * snapshot. The dispatch transmits something else: the sequence's live
 * `submission_leaves`. The orchestrator never writes those rows, so a verified
 * orchestrator signature was being read as a release over content nobody had
 * signed — leaves placed, replaced or withdrawn after signing included.
 *
 * So an orchestrator run clears this gate only when its signed leaf manifest IS
 * this sequence's current manifest (`signed-manifest-covers-sequence.ts`). A
 * signature over different content reports `unsigned`, not `invalid`: the
 * signature is intact, it simply does not cover this sequence — and `unsigned`
 * is the one verdict that falls through to the sequence spine, whose own digest
 * binds those leaf rows, so the remedy stays one governed click away.
 *
 * ## Why a submission can have several runs
 *
 * Re-running the orchestrator produces a new run. Only runs whose signature
 * still verifies count; the newest verifying run wins. A submission with three
 * runs where the newest failed integrity and an older one verifies is NOT
 * dispatchable on the strength of the older signature — the newest signed
 * package is the one that represents current intent, so an integrity failure
 * there is reported as `invalid`, not papered over by an older success.
 */

import { db } from '../../db.js';
import { sql } from 'drizzle-orm';
import {
  resolveSignedPackageForExport,
  type SignedExportRefusal,
} from './signed-package-export.js';
import type { ReleaseSignatureVerdict } from './dispatch-gate.js';
import { resolveSequenceReleaseSignature } from './sequence-release-signature.js';
import { signedManifestCoversSequence } from './signed-manifest-covers-sequence.js';
import { canonicalRegionOf } from '../../../shared/regulatory/region-identity.js';
import { createScopedLogger } from '../../utils/logger.js';

const log = createScopedLogger('release-signature-status');

/**
 * Submission types that require a release signature before transmit.
 *
 * Mirrors `SIGNATURE_REQUIRED_SUBMISSION_TYPES` in the orchestrator
 * (module-private there). Kept as an independent closed allowlist rather than
 * an import so a change to the orchestrator's build-time gate cannot silently
 * widen or narrow the TRANSMIT-time gate — the two are separate controls and a
 * divergence between them should surface as a test failure, not propagate
 * automatically. `releaseSignatureRequirementsAgree()` below is that test seam.
 *
 * REQUIRED: IND, NDA, BLA, MAA — every FDA-bound and EMA-bound submission that
 * crosses the §11.70 boundary via ESG / CESP.
 */
const TRANSMIT_SIGNATURE_REQUIRED_TYPES = new Set<string>(['IND', 'NDA', 'BLA', 'MAA']);

/** Whether this submission/application type requires a release signature to dispatch. */
export function isReleaseSignatureRequired(submissionType: string | null | undefined): boolean {
  if (!submissionType) return false;
  return TRANSMIT_SIGNATURE_REQUIRED_TYPES.has(submissionType.trim().toUpperCase());
}

/** Exposed so a contract test can assert this list against the orchestrator's. */
export function transmitSignatureRequiredTypes(): string[] {
  return [...TRANSMIT_SIGNATURE_REQUIRED_TYPES].sort();
}

export interface ReleaseSignatureStatus {
  verdict: ReleaseSignatureVerdict;
  /** Operator-facing detail — surfaced in the gate blocker message. */
  detail?: string;
  /** The orchestrator run the verdict came from, when one was found. */
  runId?: string;
  /** electronic_signatures.id, when a verifying signature was found. */
  signatureId?: number;
  /**
   * Which spine's answer this is. The orchestrator is consulted first and its
   * verdict stands unless it is `unsigned`; only then is the sequence's own
   * governed signature consulted. That precedence decides whether recording a
   * dispatch signature NOW can satisfy the requirement (see
   * `signingNowResolvesRelease`), so it is reported, not left for a caller to
   * infer from which ids happen to be present.
   */
  decidedBy?: 'orchestrator' | 'sequence';
}

/**
 * Would recording the sequence's own dispatch-intent signature now satisfy the
 * release-signature requirement?
 *
 * WHY THIS EXISTS. The Submission Center's Dispatch button records the
 * sequence's dispatch signature and then dispatches — one governed click. For
 * IND / NDA / BLA / MAA the dispatch gate requires a release signature to
 * already exist, and on the submissions spine the release signature IS that
 * dispatch signature (`sequence-release-signature.ts`, RELEASE_INTENT). A
 * button gated on the pre-signing verdict therefore never rendered, and no
 * such sequence could be dispatched from the product's own screen.
 *
 * The answer is yes only when the SEQUENCE spine decides — the orchestrator's
 * verdict stands unless it is `unsigned`, so a new sequence signature is never
 * consulted over an orchestrator run that is awaiting its signer or was
 * revoked — and only for the two verdicts a new, newest signature replaces:
 *
 *   • `unsigned` — nothing is on record; the new signature is.
 *   • `revoked`  — the newest signature decides, and the new one is newest.
 *
 * Never for `invalid`: on a frozen sequence a dispatch signature that no longer
 * binds the leaf manifest is evidence the content changed after signing, and
 * the gate blocks it whether or not a signature is required. Inviting a fresh
 * signature over it would paper over tamper evidence. Never for `undetermined`:
 * a failed lookup is not an absent signature, so nothing is offered on it.
 * `signed` needs no new signature and is not "resolved by signing".
 *
 * Pure, and the only place this rule lives. The client reads its consequence
 * (`dispatchGateOnSigning`) and never re-derives it — a client that re-derived
 * gate semantics is how the Freeze button came to read the wrong verdict.
 */
export function signingNowResolvesRelease(
  status: Pick<ReleaseSignatureStatus, 'verdict' | 'decidedBy'>,
): boolean {
  if (status.decidedBy !== 'sequence') return false;
  return status.verdict === 'unsigned' || status.verdict === 'revoked';
}

/** Map a signed-export refusal onto a dispatch verdict. */
function refusalToVerdict(refusal: SignedExportRefusal): ReleaseSignatureVerdict {
  switch (refusal) {
    // Integrity failures — a signature record exists and does not match.
    case 'seal-failed':
    case 'digest-drift':
      return 'invalid';
    case 'awaiting-signature':
      return 'awaiting';
    case 'signature-revoked':
      return 'revoked';
    // No usable signature record on this run.
    case 'not-signed':
    case 'snapshot-missing':
      return 'unsigned';
    // The run vanished between the query and the read — we cannot say.
    case 'run-not-found':
      return 'undetermined';
    // The signature lookup could not run (WO-16B finding 14). Not revoked:
    // nothing is known about the signature's standing.
    case 'signature-unverifiable':
      return 'undetermined';
  }
}

/**
 * How many orchestrator runs carry this submission's id as TEXT but have no
 * joinable FK. Used ONLY to tell "no signature" apart from "a signature the
 * join cannot see" — never to resolve a signature, which still requires the FK.
 *
 * Best-effort: a probe that cannot answer returns 0, so it can only ever
 * UPGRADE a verdict on positive evidence and never invent one.
 */
async function countUnlinkedRunsByText(submissionId: number, organizationId: number): Promise<number> {
  try {
    const rows = await db.execute(sql`
      SELECT count(*)::int AS n
        FROM submission_orchestrator_runs
       WHERE submission_id = ${String(submissionId)}
         AND submission_id_fk IS NULL
         AND organization_id = ${organizationId}
    `);
    const list = (rows as unknown as { rows?: Array<Record<string, unknown>> }).rows ?? (rows as unknown as Array<Record<string, unknown>>);
    const n = Number((Array.isArray(list) ? list : [])[0]?.n ?? 0);
    return Number.isFinite(n) && n > 0 ? n : 0;
  } catch (err) {
    log.warn('unlinked-run probe failed; reporting none', {
      err: err instanceof Error ? err.message : String(err),
      submissionId,
      organizationId,
    });
    return 0;
  }
}

/**
 * Resolve the release-signature state for a submission's SEQUENCE.
 *
 * Returns `undetermined` (never `unsigned`) on any lookup failure — a DB error
 * is not evidence that no signature exists, and the gate treats the two
 * differently on purpose.
 *
 * ── Why `sequenceNumber` is not optional in spirit ───────────────────────────
 * The run lookup below can only be keyed on the submission: orchestrator runs
 * carry `submission_id_fk`, not a sequence. But a submission holds MANY
 * sequences — 0000 original, 0001 amendment, and so on — and the caller
 * (assess-dispatch-readiness) is keyed on exactly one of them. Accepting any
 * run under the submission therefore let a release signed over sequence 0000's
 * package clear the dispatch gate for 0001, 0002 and every later sequence,
 * none of which anyone had signed. That is the failure signed-package-export.ts
 * names in its own header — "a user could orchestrate + sign package A and then
 * export package B under the same submission id" — reintroduced one layer up,
 * at the gate that decides whether the dispatch may happen at all.
 *
 * So the submission narrows the candidates and the SEQUENCE decides: a run
 * clears this sequence only when the package it signed was this sequence's.
 * The signed snapshot carries that identity (`descriptor.sequenceNumber`), so
 * the comparison is against what was actually signed, not against anything the
 * caller supplied alongside it.
 *
 * `sequenceNumber` is typed optional only so an existing caller that genuinely
 * assesses a submission as a whole keeps compiling; when it is absent the old
 * submission-wide behaviour applies and the detail string says so, rather than
 * silently implying a sequence was checked.
 */
async function resolveOrchestratorReleaseSignature(params: {
  submissionId: number;
  organizationId: number;
  /** The eCTD sequence being assessed, e.g. '0001'. */
  sequenceNumber?: string | null;
  /**
   * `ectd_sequences.id` — the key the sequence's LIVE leaves are on.
   *
   * Needed because the orchestrator signs its own composed package and never
   * writes `submission_leaves` (see signed-manifest-covers-sequence.ts), so
   * matching `descriptor.sequenceNumber` establishes only that the signature
   * NAMES this sequence. Whether it COVERS what would be transmitted is a
   * question about these rows.
   */
  sequenceId?: number | null;
  /** That sequence's region, in any of the platform's vocabularies. */
  region?: string | null;
}): Promise<ReleaseSignatureStatus> {
  const { submissionId, organizationId } = params;
  const sequenceId =
    typeof params.sequenceId === 'number' && Number.isFinite(params.sequenceId) && params.sequenceId > 0
      ? params.sequenceId
      : null;
  const sequenceNumber =
    typeof params.sequenceNumber === 'string' && params.sequenceNumber.trim() !== ''
      ? params.sequenceNumber.trim()
      : null;
  /* Resolved through the region registry, never compared as a string: the two
     spines spell one jurisdiction differently ('fda' on the sequence row, 'US'
     on the signed descriptor), so a !== would refuse every real dispatch.
     undefined means the registry does not recognise it, which is not evidence
     that it differs — see the region tests. */
  const region = canonicalRegionOf(params.region);

  if (!Number.isFinite(submissionId) || submissionId <= 0) {
    return { verdict: 'undetermined', detail: 'invalid submission id' };
  }
  if (!Number.isFinite(organizationId) || organizationId <= 0) {
    return { verdict: 'undetermined', detail: 'invalid organization context' };
  }

  let runIds: string[];
  try {
    // Newest first: the most recent signed run represents current intent.
    const rows = await db.execute(sql`
      SELECT run_id
        FROM submission_orchestrator_runs
       WHERE submission_id_fk = ${submissionId}
         AND organization_id = ${organizationId}
       ORDER BY started_at DESC
       LIMIT 25
    `);
    const list = (rows as unknown as { rows?: Array<Record<string, unknown>> }).rows ?? (rows as unknown as Array<Record<string, unknown>>);
    runIds = (Array.isArray(list) ? list : [])
      .map(r => (r?.run_id == null ? '' : String(r.run_id)))
      .filter(Boolean);
  } catch (err) {
    // Fail closed and SAY SO. Reporting 'unsigned' here would let a DB outage
    // read as "this submission simply has no signature", which the gate would
    // then treat as a normal, fixable state instead of an unknown one.
    log.warn('release-signature lookup failed; reporting undetermined', {
      err: err instanceof Error ? err.message : String(err),
      submissionId,
      organizationId,
    });
    return {
      verdict: 'undetermined',
      detail: 'the orchestrator run lookup failed',
    };
  }

  if (runIds.length === 0) {
    /* Nothing JOINED — which is not the same as nothing SIGNED.
       submission_orchestrator_runs.submission_id_fk is optional by design (see
       OrchestratorInputs.submissionFk): the orchestrator writes it only when a
       caller supplies one, and a caller that does not leaves the column NULL
       "until a per-tenant backfill resolves it". The lookup above joins on
       exactly that column, so an unlinked run is invisible to it — and
       reporting 'unsigned' then tells a customer who HAS orchestrated and
       signed a release that they have not signed one. Worse, 'unsigned' reads
       as a fixable state whose fix is to sign, and signing again produces
       another unlinked run.
       So before concluding absence, ask whether runs exist that simply cannot
       be joined. The TEXT probe uses the same identity rule
       loadSubmissionFkBySubmissionIdText applies — the numeric id as text, and
       nothing else — so it is the same claim about identity that the FK
       resolution would have made, not a looser guess. */
    const unlinked = await countUnlinkedRunsByText(submissionId, organizationId);
    if (unlinked > 0) {
      return {
        verdict: 'undetermined',
        detail:
          `${unlinked} orchestrator run(s) carry this submission's id but are not linked to it ` +
          `(submission_id_fk is NULL), so whether a release was signed cannot be determined. ` +
          `Resolve the FK for those runs; signing again would only add another unlinked run.`,
      };
    }
    return {
      verdict: 'unsigned',
      detail: 'no orchestrator run is linked to this submission',
    };
  }

  // Walk newest-first. The first run that yields a definitive answer wins.
  // An integrity failure on the newest run is returned immediately rather than
  // falling through to an older, still-valid signature.
  let firstNonUnsigned: ReleaseSignatureStatus | null = null;
  /** Runs that carry a valid signature over a DIFFERENT sequence. */
  let signedOtherSequences = 0;
  /** Runs that signed this sequence NUMBER, but in another region. */
  let signedOtherRegions = 0;
  /** Runs that signed this sequence, over a manifest it no longer holds. */
  const signedOtherManifests: string[] = [];

  for (const runId of runIds) {
    const result = await resolveSignedPackageForExport({ runId, organizationId });

    if (result.ok) {
      const signedSequence = result.descriptor.sequenceNumber;
      // A perfectly valid signature over ANOTHER sequence of this submission
      // is not this sequence's signature. Skip it and keep looking: it is not
      // evidence about this package in either direction, so it must neither
      // clear the gate nor block it.
      if (sequenceNumber !== null && String(signedSequence ?? '').trim() !== sequenceNumber) {
        signedOtherSequences++;
        continue;
      }
      /* Same number, different jurisdiction. Sequence numbers restart per
         region, so '0000' is the FDA original AND the EU original; a release
         over one is no evidence about the other. Excluded only when BOTH sides
         resolve to a known region and they differ — an unresolvable region is
         unknown, not different, and must not block a dispatch. */
      const signedRegion = canonicalRegionOf(result.descriptor.region);
      if (region !== undefined && signedRegion !== undefined && signedRegion !== region) {
        signedOtherRegions++;
        continue;
      }
      /* THE signature binds what ships, or it is not this sequence's release.
         resolveSignedPackageForExport verified the signature against its own
         frozen snapshot; it does not — cannot — know what the sequence's
         `submission_leaves` hold now, and those rows are what the dispatch
         transmits. So ask. A signature over a manifest this sequence no
         longer holds is skipped exactly as one over another sequence is: it
         is not evidence about this package in either direction. */
      if (sequenceId !== null) {
        const coverage = await signedManifestCoversSequence({
          signedLeaves: result.descriptor.leaves ?? [],
          sequenceId,
          submissionId,
          organizationId,
          region: region ?? signedRegion,
          recordedPackageIdentity: result.descriptor.recordedPackageIdentity,
        });
        if ('unknown' in coverage) {
          // Fail closed and say which half is unknown. An unreadable sequence
          // is not a verified one, and it is not an unsigned one either.
          return { verdict: 'undetermined', runId, detail: coverage.detail };
        }
        if (!coverage.covers) {
          signedOtherManifests.push(`run ${runId}: ${coverage.detail}`);
          continue;
        }
        return {
          verdict: 'signed',
          runId,
          signatureId: result.descriptor.signatureId,
          detail:
            `verified against run ${runId} for sequence ${sequenceNumber ?? '(unnamed)'}; ` +
            `its signed manifest is this sequence's ${coverage.leafCount} leaf/leaves ` +
            `(${coverage.corroboratedLeaves} matched on their eCTD index-md5)`,
        };
      }

      /* No sequence id: the live leaves cannot be addressed, so coverage was
         not checked. The verdict says so rather than letting a clear answer
         imply a check that did not run. */
      return {
        verdict: 'signed',
        runId,
        signatureId: result.descriptor.signatureId,
        detail: sequenceNumber
          ? `verified against run ${runId} for sequence ${sequenceNumber}; no sequence id was supplied, so whether its signed manifest is still this sequence's content was not checked`
          : `verified against run ${runId}; no sequence was named, so whether its signed manifest is still the sequence's content was not checked`,
      };
    }

    const verdict = refusalToVerdict(result.refusal);

    // Integrity failure short-circuits — never look for an older signature to
    // excuse a tampered newer one.
    if (verdict === 'invalid') {
      return { verdict, runId, detail: result.detail };
    }

    // Remember the most recent non-trivial state (awaiting / revoked /
    // undetermined) so we report THAT rather than a bare 'unsigned' when no
    // run ever produced a verifying signature.
    if (!firstNonUnsigned && verdict !== 'unsigned') {
      firstNonUnsigned = { verdict, runId, detail: result.detail };
    }
  }

  if (firstNonUnsigned) return firstNonUnsigned;

  // Say which of the two "unsigned" states this is. "There is no signature"
  // and "there is a signature, over a different sequence" send an operator to
  // completely different places, and the second one is the one that used to
  // clear this gate.
  if (signedOtherManifests.length > 0) {
    return {
      verdict: 'unsigned',
      detail:
        `no release signature covers sequence ${sequenceNumber ?? '(unnamed)'} as it now stands — ` +
        `${signedOtherManifests.length} run(s) signed it over different content. ` +
        `${signedOtherManifests.join('; ')}. ` +
        `Sign this sequence for release, which binds the leaf manifest that would be transmitted.`,
    };
  }

  if (signedOtherRegions > 0) {
    return {
      verdict: 'unsigned',
      detail:
        `no release signature covers sequence ${sequenceNumber} in region ${region} — ` +
        `${signedOtherRegions} run(s) signed that sequence number in a different region`,
    };
  }

  if (signedOtherSequences > 0) {
    return {
      verdict: 'unsigned',
      detail:
        `no release signature covers sequence ${sequenceNumber} — ` +
        `${signedOtherSequences} run(s) under this submission are signed, but over a different sequence`,
    };
  }

  return {
    verdict: 'unsigned',
    detail: `no run among ${runIds.length} carries a completed release signature`,
  };
}

/**
 * Resolve the release-signature state for a submission's SEQUENCE, across BOTH
 * spines a release can be signed on.
 *
 * ── Why two ──────────────────────────────────────────────────────────────────
 * The orchestrator spine (`package.sign` on a run) was the only one this
 * resolver could see. But a sequence can be authored and released entirely
 * through the SUBMISSIONS spine, whose governed sign on `ectd-sequence:<id>`
 * persists an `electronic_signatures` row bound by sha256 to that sequence's
 * row and its ordered leaf manifest — the very artifact the dispatch would
 * transmit. Such a submission has no orchestrator run at all, so it was
 * reported `unsigned`, and since the gate REQUIRES a release signature for
 * IND / NDA / BLA / MAA — every type it applies to — `dispatchSequence` and
 * `transmitSequence` were unreachable for it no matter how correctly the
 * operator signed. The gate was not protecting anything there; it was denying a
 * signature that existed.
 *
 * ── The composition, and why it is this way round ────────────────────────────
 * The orchestrator spine answers first and its answer stands whenever it is
 * DEFINITE — `signed`, `invalid`, `awaiting` or `revoked`. In particular a
 * tampered orchestrator signature reports `invalid` and can never be rescued by
 * a valid signature on the other spine.
 *
 * The second spine is consulted for exactly one verdict: `unsigned`, a
 * determinate "the orchestrator spine holds no signature for this sequence".
 * Deliberately NOT for `undetermined`: an outage there means an `invalid` we
 * cannot see, so clearing on the other spine could let a tampered signature
 * through. Undetermined blocks, and an undetermined lookup is not an absent
 * requirement.
 *
 * From there the second spine's own answer governs, including its integrity
 * failures — a drifted or revoked sequence signature blocks even though the
 * orchestrator spine had nothing to say. Only its `unsigned` falls back, and
 * then the detail names both spines rather than implying only one was checked.
 *
 * `sequenceId` is optional so a caller that has only the submission keeps
 * compiling; without it the second spine cannot be addressed at all (it is
 * keyed on the sequence, not the submission), the orchestrator signature's
 * coverage of the live leaves cannot be checked either, and the orchestrator
 * answer is returned unchanged — with a detail that names what was not
 * checked.
 */
export async function resolveReleaseSignatureStatus(params: {
  submissionId: number;
  organizationId: number;
  /** The eCTD sequence being assessed, e.g. '0001'. */
  sequenceNumber?: string | null;
  /**
   * `ectd_sequences.id` — the key the submissions spine's signature is on, and
   * the key this sequence's live leaves are on. Without it neither the second
   * spine nor the orchestrator signature's coverage of those leaves can be
   * checked, and the detail string says so.
   */
  sequenceId?: number | null;
  /** That sequence's region, in any of the platform's vocabularies. */
  region?: string | null;
}): Promise<ReleaseSignatureStatus> {
  const orchestrator = await resolveOrchestratorReleaseSignature(params);
  if (orchestrator.verdict !== 'unsigned') return { ...orchestrator, decidedBy: 'orchestrator' };

  const sequenceId =
    typeof params.sequenceId === 'number' && Number.isFinite(params.sequenceId) && params.sequenceId > 0
      ? params.sequenceId
      : null;
  // No sequence to consult: the orchestrator's `unsigned` is the answer, and a
  // sequence signature could not be seen by this resolver even if one were
  // recorded — so it is the orchestrator that decided.
  if (sequenceId === null) return { ...orchestrator, decidedBy: 'orchestrator' };

  const sequenceSpine = await resolveSequenceReleaseSignature({
    sequenceId,
    organizationId: params.organizationId,
  });

  if (sequenceSpine.verdict === 'unsigned') {
    return {
      verdict: 'unsigned',
      detail:
        `${orchestrator.detail ?? 'no orchestrator release signature'}; ` +
        `and ${sequenceSpine.detail ?? 'no signature on the sequence itself'}`,
      decidedBy: 'sequence',
    };
  }

  return {
    verdict: sequenceSpine.verdict,
    detail: sequenceSpine.detail,
    signatureId: sequenceSpine.signatureId,
    decidedBy: 'sequence',
  };
}

export default {
  resolveReleaseSignatureStatus,
  isReleaseSignatureRequired,
  transmitSignatureRequiredTypes,
};

/**
 * @fileoverview Submission-Package Orchestrator
 * @module server/services/submission-package-orchestrator
 *
 * The meta-service that sequences artifacts → sections → modules → ZIP for an
 * IND/NDA/BLA/510(k) submission. Closes the gap identified in the audit:
 * services exist (csr-builder, module3Composer, m2-summary-builders, the canonical
 * ectd/assemble-from-core packager)
 * but no single coordinator runs them in dependency order, regenerates downstream when
 * upstream changes, or records an audit log of inputs to the package.
 *
 * Pipeline:
 *
 *   ┌──────────────┐   ┌──────────────────┐   ┌──────────────────┐
 *   │ Source data  │──▶│ Module 3 (S/P/   │──▶│ M2.3 Quality OS  │──┐
 *   │ ingestion    │   │ A/R) composition │   │                  │  │
 *   └──────────────┘   └──────────────────┘   └──────────────────┘  │
 *   ┌──────────────┐   ┌──────────────────┐   ┌──────────────────┐  │
 *   │ Nonclinical  │──▶│ Module 4 stubs   │──▶│ M2.4 Nonclin OV  │──┤   ┌────────────┐
 *   │ studies      │   │                  │   │                  │  ├──▶│ M1 admin   │
 *   └──────────────┘   └──────────────────┘   └──────────────────┘  │   └────────────┘
 *   ┌──────────────┐   ┌──────────────────┐   ┌──────────────────┐  │         │
 *   │ Study DB     │──▶│ CSR §10–§12      │──▶│ M2.7 Clinical Sm │──┤         ▼
 *   │ (CDISC)      │   │ tabulations      │   │                  │  │   ┌────────────┐
 *   └──────────────┘   └──────────────────┘   └──────────────────┘  └──▶│ Validator  │
 *                                                                       │ + ZIP +    │
 *                                                                       │ Audit log  │
